<?php defined('ABSPATH') || exit;
$state=Aster_Phase_One::state($order); $shipment=Aster_Phase_One::shipment($order);
$has_shipment=!empty($shipment['tracking_number']) || !empty($shipment['events']) || !empty($shipment['last_scan']);
?>
<article class="ae-order" data-order="<?php echo esc_attr($order->get_order_number()); ?>">
<?php if (Aster_Phase_One::fixture($order)): ?><p class="ae-preview-label">LOCAL PREVIEW · Test order and simulated payment status. No payment was made.</p><?php endif; ?>
<header class="ae-order-heading"><div><div class="ae-order-meta"><p class="aster-eyebrow">YOUR ORDER · #<?php echo esc_html($order->get_order_number()); ?></p><span class="ae-status" data-state="<?php echo esc_attr($state['key']); ?>"><?php echo esc_html($state['label']); ?></span></div><?php $title_tag=is_account_page() || $embedded ? 'h2' : 'h1'; ?><<?php echo $title_tag; ?> class="ae-result-title"><?php echo esc_html($state['heading']); ?></<?php echo $title_tag; ?>><p><?php echo esc_html($state['message']); ?></p></div></header>
<div class="ae-order-grid"><section class="ae-order-summary" aria-label="Order summary"><h2>Your pieces</h2>
<?php foreach ($order->get_items() as $item): $product=$item->get_product(); $image=$product ? aster_storefront_product_image((string)$product->get_meta('_aster_catalog_key')) : null;
if ($product && $product->get_meta('_aster_fixture')==='phase-one-20261016') $image=Aster_Phase_One::asset('olive-cup.png'); ?>
<div class="ae-order-item"><?php if ($image): ?><img src="<?php echo esc_url($image); ?>" width="88" height="88" alt="<?php echo esc_attr($item->get_name()); ?>"><?php endif; ?><div><h3><?php echo esc_html($item->get_name()); ?></h3><p>Quantity <?php echo esc_html($item->get_quantity()); ?></p><?php echo wp_kses_post(wc_display_item_meta($item,['echo'=>false])); ?></div><strong><?php echo wp_kses_post(wc_price($item->get_total(),['currency'=>$order->get_currency()])); ?></strong></div>
<?php endforeach; ?>
<dl class="ae-totals"><dt>Items</dt><dd><?php echo wp_kses_post(wc_price($order->get_subtotal(),['currency'=>$order->get_currency()])); ?></dd><dt>Shipping</dt><dd><?php echo wp_kses_post(wc_price($order->get_shipping_total(),['currency'=>$order->get_currency()])); ?></dd>
<?php if ((float)$order->get_discount_total()>0): ?><dt>Discount</dt><dd>−<?php echo wp_kses_post(wc_price($order->get_discount_total(),['currency'=>$order->get_currency()])); ?></dd><?php endif; ?>
<?php if ((float)$order->get_total_tax()>0): ?><dt>Tax</dt><dd><?php echo wp_kses_post(wc_price($order->get_total_tax(),['currency'=>$order->get_currency()])); ?></dd><?php endif; ?>
<dt class="ae-total">Total <small><?php echo esc_html($order->get_currency()); ?></small></dt><dd class="ae-total"><?php echo wp_kses_post(wc_price($order->get_total(),['currency'=>$order->get_currency()])); ?></dd>
<?php if ((float)$order->get_total_refunded()>0): ?><dt>Refund recorded</dt><dd><?php echo wp_kses_post(wc_price($order->get_total_refunded(),['currency'=>$order->get_currency()])); ?></dd><dt>After recorded refunds</dt><dd><?php echo wp_kses_post(wc_price(max(0,(float)$order->get_total()-(float)$order->get_total_refunded()),['currency'=>$order->get_currency()])); ?></dd><?php endif; ?></dl>
<?php if ($order->get_customer_note()): ?><div class="ae-order-note"><h3>Your order note</h3><p><?php echo nl2br(esc_html($order->get_customer_note())); ?></p><small>Requested dates and changes need confirmation by email.</small></div><?php endif; ?>
<div class="ae-order-actions"><?php if ($allow_payment && $state['can_resume']): ?><a class="ae-button" href="<?php echo esc_url($order->get_checkout_payment_url()); ?>">Continue this order</a><?php endif; ?><button class="ae-refresh" type="button">Check latest status</button><button class="ae-help" type="button">Get help with this order</button></div>
<?php if (class_exists('Aster_Purchase_Reviews') && Aster_Purchase_Reviews::eligible($order)): ?><p class="ae-order-footnote"><a href="<?php echo esc_url(add_query_arg('order',$order->get_id(),Aster_Care::url('reviews'))); ?>">Review this purchase →</a> · A private email link or the purchasing account is required.</p><?php endif; ?><p class="ae-order-footnote">Keep your order number. You can check it with your checkout email on the <a href="<?php echo esc_url(home_url('/order-status/')); ?>">order status page</a>.</p></section>
<aside class="ae-shipment" aria-label="Shipping updates"><p class="aster-eyebrow">DELIVERY</p><h2><?php echo $has_shipment ? 'Your shipment' : (in_array($state['key'],['paid'],true) ? 'Preparing your order' : 'Shipping updates'); ?></h2>
<?php if (!$has_shipment): ?><p><?php echo $state['key']==='paid' ? 'Carrier and tracking details will appear here after dispatch.' : 'Tracking details will appear here when your order is ready to ship.'; ?></p><?php else: ?>
<dl><?php foreach (['carrier'=>'Carrier','tracking_number'=>'Tracking number','estimated_arrival'=>'Estimated arrival','last_scan'=>'Latest update'] as $k=>$label): if (empty($shipment[$k])) continue; ?><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($shipment[$k]); ?></dd><?php endforeach; ?></dl>
<?php if (!empty($shipment['events'])): ?><ol class="ae-events"><?php foreach ($shipment['events'] as $e): ?><li><strong><?php echo esc_html($e['label']); ?></strong><?php if ($e['detail']): ?><p><?php echo esc_html($e['detail']); ?></p><?php endif; ?><?php if ($e['occurred_at']): ?><small><?php echo esc_html($e['occurred_at']); ?></small><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?>
<?php if (!empty($shipment['tracking_url'])): ?><a class="ae-button ae-secondary" href="<?php echo esc_url($shipment['tracking_url']); ?>" target="_blank" rel="noopener noreferrer">Track package <span aria-hidden="true">↗</span></a><?php endif; ?>
<?php endif; ?><p class="ae-shipment-help"><a href="<?php echo esc_url(aster_storefront_url('/shipping-returns')); ?>">Shipping &amp; returns →</a></p></aside></div>
</article>
